def ispr(x, y, m):
	if x <= 0 and y <= 0 and (m > x or m > y):
		return -1

	def ispr_recur(x, y, m, n):
		if (x >= m or y >= m):
			return n
		else:
			n += 1
			return 1 + min(ispr_recur(x + y, y, m, n), ispr_recur(x, x + y, m, n))

	return ispr_recur(x, y, m, 0)

