def solve(l):
	if len(l) == 0:
		return 0
	c, e = calcCost(l), calcEffect(l)
	e = map(lambda x: -x, e)
	i, s = min(enumerate(zip(c, e)), key=operator.itemgetter(1))
	return s[0] + solve(l[:i] + l[i+1:])

def calcCost(l):
	c = 0
	r = list()
	# forward counting
	for x in l:
		r.append(c)
		if x == 1:
			c += 1
	# backward counting
	c = 0
	for i, x in enumerate(reversed(l)):
		r[-1 - i] += c
		if x == 0:
			c += 1
	return r

def calcEffect(l):
	for i, x in enumerate(l):
		yield i if x == 0 else len(l)-1-i

